function updateSeoMetadata(){
 const path=location.pathname.endsWith('/')?location.pathname:location.pathname+'/';const m=siteSeo.pages[path]||siteSeo.pages['/'];
 document.title=m.title;
 const values={'meta[name="description"]':['content',m.description],'link[rel="canonical"]':['href',siteSeo.origin+m.canonical],'meta[property="og:title"]':['content',m.title],'meta[property="og:description"]':['content',m.description],'meta[property="og:url"]':['content',siteSeo.origin+m.canonical],'meta[name="twitter:title"]':['content',m.title],'meta[name="twitter:description"]':['content',m.description]};
 for(const [selector,[attr,value]] of Object.entries(values)){const el=document.querySelector(selector);if(el)el.setAttribute(attr,value)}
 const graph=document.querySelector('#site-structured-data');if(graph){const base=JSON.parse(graph.textContent);const web=base['@graph'].find(x=>x['@type']==='WebPage');web['@id']=siteSeo.origin+m.canonical+'#webpage';web.url=siteSeo.origin+m.canonical;web.name=m.title;web.description=m.description;const breadcrumb=base['@graph'].find(x=>x['@type']==='BreadcrumbList');breadcrumb['@id']=siteSeo.origin+m.canonical+'#breadcrumb';breadcrumb.itemListElement=[{'@type':'ListItem',position:1,name:'Home',item:siteSeo.origin+'/'}];if(m.canonical!=='/')breadcrumb.itemListElement.push({'@type':'ListItem',position:2,name:m.name,item:siteSeo.origin+m.canonical});web.breadcrumb={'@id':breadcrumb['@id']};graph.textContent=JSON.stringify(base)}
}
